# Kartenausschnitt: Österreich mit angrenzenden Regionen
KARTE_LAT_MIN, KARTE_LAT_MAX = 45.6, 49.6
KARTE_LON_MIN, KARTE_LON_MAX = 8.6, 17.8


@st.cache_data(ttl=10800, show_spinner=False)
def hole_niederschlagsraster(stunden=72, maschen=0.20,
                             modell='best_match'):
    """
    Lädt ein Niederschlagsraster über Österreich und die angrenzenden
    Regionen für die Modellprognose.

    Open-Meteo nimmt mehrere Koordinaten je Anfrage entgegen. Das Gitter
    wird in Blöcken abgerufen, damit die Anfragen handhabbar bleiben.
    Verwendet wird jeweils das höchstauflösende verfügbare Modell.

    Rückgabe: dict mit Gitterachsen, Zeitachse und Werten
    als verschachtelte Liste [zeit][lat][lon] in mm/h.
    """
    lats = np.round(np.arange(KARTE_LAT_MIN, KARTE_LAT_MAX + 1e-9, maschen), 4)
    lons = np.round(np.arange(KARTE_LON_MIN, KARTE_LON_MAX + 1e-9, maschen), 4)
    n_la, n_lo = len(lats), len(lons)

    punkte = [(la, lo) for la in lats for lo in lons]
    n_zeit = None
    zeiten = None
    werte_alle = [None] * len(punkte)

    # In Blöcken abrufen, damit die URL nicht zu lang wird
    blockgroesse = 200
    for start in range(0, len(punkte), blockgroesse):
        block = punkte[start:start + blockgroesse]
        params = {
            'latitude': ','.join(f"{p[0]:.4f}" for p in block),
            'longitude': ','.join(f"{p[1]:.4f}" for p in block),
            'hourly': 'precipitation',
            'forecast_hours': min(int(stunden), 96),
            'models': modell,
            'timezone': 'Europe/Vienna',
        }
        try:
            r = requests.get('https://api.open-meteo.com/v1/forecast',
                             params=params, timeout=60)
            daten = r.json()
        except Exception:
            continue
        if isinstance(daten, dict):
            daten = [daten]
        if not isinstance(daten, list):
            continue
        for k, eintrag in enumerate(daten):
            h = (eintrag or {}).get('hourly') or {}
            if zeiten is None and 'time' in h:
                zeiten = h['time']
                n_zeit = len(zeiten)
            werte_alle[start + k] = h.get('precipitation')

    if zeiten is None or n_zeit is None:
        return None

    raster = [[[0.0] * n_lo for _ in range(n_la)] for _ in range(n_zeit)]
    for idx, werte in enumerate(werte_alle):
        if not werte:
            continue
        i_la, i_lo = divmod(idx, n_lo)
        if i_la >= n_la:
            break
        for t in range(min(n_zeit, len(werte))):
            v = werte[t]
            raster[t][i_la][i_lo] = float(v) if v is not None else 0.0

    return {
        'lats': [float(x) for x in lats],
        'lons': [float(x) for x in lons],
        'zeiten': zeiten,
        'raster': raster,
        'maschen': float(maschen),
        'modell': modell,
    }


@st.cache_data(ttl=1800, show_spinner=False)
def hole_sonnenzeiten(lat, lon, tage):
    """Sonnenauf- und -untergang je Tag."""
    try:
        r = requests.get('https://api.open-meteo.com/v1/forecast',
                         params={'latitude': lat, 'longitude': lon,
                                 'daily': 'sunrise,sunset',
                                 'forecast_days': min(tage, 16),
                                 'timezone': 'Europe/Vienna'}, timeout=10)
        d = r.json().get('daily', {})
    except Exception:
        return None
    if not d or 'sunrise' not in d:
        return None
    return pd.DataFrame({
        'datum': pd.to_datetime(d['time']).date,
        'aufgang': pd.to_datetime(d['sunrise']),
        'untergang': pd.to_datetime(d['sunset'])})


def lade_alle_daten(lat, lon, af, tage, fortschritt=None, standorthoehe=None,
                    bodenart=BODENART_STANDARD):
    schritte = len(HAUPTLAUFE) + len(ENSEMBLE_MODELLE) + 2
    schritt = 0
    haupt_daten, ensemble_daten = {}, {}

    # Höhendifferenz Standort ↔ Modellgitter bestimmen
    modellhoehe = hole_modellhoehe(lat, lon)
    delta_h = None
    if standorthoehe is not None and modellhoehe is not None:
        delta_h = float(standorthoehe) - float(modellhoehe)

    # Standorthöhe ins af-Dict schreiben damit Bewertung darauf zugreifen kann
    if standorthoehe is not None:
        af['_standorthoehe'] = float(standorthoehe)

    for name in HAUPTLAUFE:
        schritt += 1
        if fortschritt: fortschritt.progress(schritt/schritte, text=f"Lade {name} …")
        df = hole_hauptlauf(lat, lon, name, tage)
        if df is not None and not df.empty:
            haupt_daten[name] = hoehenkorrektur(df, delta_h)

    # Bewölkungsdaten aus einem Hauptlauf als Referenz für die Ensembles
    _wolken_ref = None
    for _hd in haupt_daten.values():
        if 'wolken' in _hd.columns and _hd['wolken'].notna().any():
            _spalten_ref = ['time', 'wolken', 'wolken_tief', 'wolken_mittel']
            for _z in ('cape', 'gefuehlt'):
                if _z in _hd.columns:
                    _spalten_ref.append(_z)
            _wolken_ref = _hd[_spalten_ref].copy()
            break

    for name, cfg in ENSEMBLE_MODELLE.items():
        schritt += 1
        if fortschritt:
            fortschritt.progress(schritt/schritte,
                                 text=f"Lade {name} ({cfg['mitglieder']} Mitgl.) …")
        df = hole_ensemble(lat, lon, name, tage)
        if df is not None and not df.empty:
            df = hoehenkorrektur(df, delta_h)
            ensemble_daten[name] = bewerte_ensemble_df(df, af, _wolken_ref)

    schritt += 1
    if fortschritt: fortschritt.progress(schritt/schritte, text="Lade Bodendaten …")
    boden = hole_bodendaten(lat, lon, tage)
    bodenindex = berechne_bodenindex(boden, bodenart)
    infil = berechne_infiltration(boden['hourly']) if boden else None

    schritt += 1
    if fortschritt: fortschritt.progress(schritt/schritte, text="Lade Sonnenstände …")
    sonne = hole_sonnenzeiten(lat, lon, tage)

    return {'haupt': haupt_daten, 'ensemble': ensemble_daten,
            'bodenindex': bodenindex, 'boden': boden, 'infiltration': infil,
            'sonne': sonne, 'modellhoehe': modellhoehe,
            'standorthoehe': standorthoehe, 'delta_h': delta_h}


