def parameter_editor(fall_name, basis):
    # Alle Merkmale des Anwendungsfalls übernehmen, damit Flags wie
    # 'outdoor' oder 'alpin_bewölkung' nicht verloren gehen.
    af = dict(basis)
    af['name'] = fall_name
    af.setdefault('beschreibung', '')
    af.setdefault('modus', 'standard')
    af.setdefault('boden_relevant', False)
    af.setdefault('duerre_relevant', False)
    felder = FROST_FELDER if af['modus'] == 'frost' else PARAM_FELDER
    with st.expander("Richtwerte anpassen (optional)", expanded=False):
        st.caption("Fachliche Vorgabewerte. Sie lassen sich an Standort, "
                   "Bodenart und eigene Erfahrung anpassen.")
        spalten = st.columns(2)
        i = 0
        for key, label, einheit, mn, mx, step in felder:
            if key in basis or (key == 'trockenfenster_h'
                                and af['modus'] != 'frost'):
                with spalten[i % 2]:
                    af[key] = st.number_input(
                        f"{label} ({einheit})", min_value=mn, max_value=mx,
                        value=float(basis.get(key, 0.0)), step=step,
                        key=f"{fall_name}__{key}")
                i += 1
        if af['modus'] != 'frost':
            af['boden_relevant'] = st.checkbox(
                "Bodenzustand einbeziehen", value=af['boden_relevant'],
                key=f"{fall_name}__boden")
    if 'trockenfenster_h' in af:
        af['trockenfenster_h'] = int(af['trockenfenster_h'])
    return af


# ============================================================
# KOPFBEREICH UND EINGABE
# ============================================================


# ---------- Kurze Einführung beim ersten Aufruf ----------
if 'konsens' not in st.session_state:
    st.markdown(
        '<div class="ew-intro">'
        '<b>So funktioniert es:</b> Standort eingeben, Tätigkeit wählen, '
        'Analyse starten. EnsembleWetter vergleicht bis zu elf Wettermodelle '
        'und zeigt Ihnen stundengenau, wann die Bedingungen für Ihr Vorhaben '
        'passen — statt nur, wie das Wetter wird.'
        '</div>', unsafe_allow_html=True)

st.markdown('<div class="ew-formcard">', unsafe_allow_html=True)

if 'ew_favoriten' not in st.session_state:
    st.session_state['ew_favoriten'] = []

# ---------- Schritt 1: Standort ----------
st.markdown('<div class="ew-step"><span class="ew-num">1</span>'
            'Wo?</div>', unsafe_allow_html=True)

s1, s2 = st.columns([3, 1])
with s1:
    ort_eingabe = st.text_input(
        "Standort", value='', label_visibility="collapsed",
        placeholder="Ort oder Postleitzahl eingeben, z. B. 3250 oder Wieselburg")
with s2:
    fav_speichern = st.button("Merken", use_container_width=True,
                              help="Diesen Standort zur Schnellauswahl hinzufügen")

favs = st.session_state['ew_favoriten']
if favs:
    fav_labels = ['Gespeicherte Orte …'] + favs
    fav_wahl = st.selectbox("Gespeicherte Orte", fav_labels,
                            label_visibility="collapsed", key='fav_dropdown')
    if fav_wahl and fav_wahl != 'Gespeicherte Orte …':
        ort_eingabe = fav_wahl

if fav_speichern and ort_eingabe:
    if ort_eingabe not in favs:
        favs.insert(0, ort_eingabe)
        if len(favs) > 10:
            favs.pop()
        st.session_state['ew_favoriten'] = favs
        st.success(f"„{ort_eingabe}“ gemerkt.")

# ---------- Schritt 2: Vorhaben ----------
st.markdown('<div class="ew-step"><span class="ew-num">2</span>'
            'Was haben Sie vor?</div>', unsafe_allow_html=True)

v1, v2 = st.columns([1, 1])
with v1:
    kategorie = st.selectbox("Bereich", list(ANWENDUNGSFAELLE.keys()), index=0,
                             help="Zuerst den Tätigkeitsbereich wählen")
with v2:
    faelle = list(ANWENDUNGSFAELLE[kategorie].keys())
    fall_name = st.selectbox("Tätigkeit", faelle, index=0)

basis = ANWENDUNGSFAELLE[kategorie][fall_name]
st.markdown(f'<div class="ew-fallinfo">{basis.get("beschreibung", "")}</div>',
            unsafe_allow_html=True)

# ---------- Schritt 3: Zeitraum und Feineinstellung ----------
st.markdown('<div class="ew-step"><span class="ew-num">3</span>'
            'Für welchen Zeitraum?</div>', unsafe_allow_html=True)

tage = st.slider("Prognosezeitraum", 1, 14, 5,
                 label_visibility="collapsed",
                 format="%d Tage")
if tage > 7:
    st.markdown(
        '<div class="ew-warn">Ab dem achten Tag sinkt die Aussagekraft '
        'deutlich. Für die Planung konkreter Arbeitsschritte sind die '
        'ersten drei bis fünf Tage maßgeblich.</div>',
        unsafe_allow_html=True)

af_aktiv = parameter_editor(fall_name, basis)

# Bodenart nur bei bodengebundenen Tätigkeiten
bodenart_wahl = BODENART_STANDARD
if af_aktiv.get('boden_relevant'):
    bodenart_wahl = st.selectbox(
        "Bodenart am Schlag",
        list(BODENARTEN.keys()),
        index=list(BODENARTEN.keys()).index(BODENART_STANDARD),
        help="Bestimmt, wie schnell der Boden nach Regen wieder "
             "befahrbar ist")
    st.markdown(
        f'<div class="ew-fallinfo">'
        f'{BODENARTEN[bodenart_wahl]["hinweis"]}</div>',
        unsafe_allow_html=True)

gewaehlter_ort = None
if ort_eingabe:
    treffer = geocode_ort(ort_eingabe)
    if not treffer:
        st.error(f"„{ort_eingabe}“ wurde nicht gefunden. Bitte die "
                 f"Schreibweise prüfen oder die Postleitzahl verwenden.")
    elif len(treffer) == 1:
        gewaehlter_ort = treffer[0]
    else:
        labels = [t['label'] for t in treffer]
        wahl = st.selectbox("Mehrere Orte gefunden — bitte auswählen", labels)
        gewaehlter_ort = treffer[labels.index(wahl)]

los = st.button("Analyse starten", type="primary", use_container_width=True)
st.markdown('</div>', unsafe_allow_html=True)

LADETEXTE = [
    "Wettermodelle werden abgerufen …",
    "Ensemble-Vorhersagen werden gesammelt …",
    "Bodenzustand wird ermittelt …",
    "Sonnenstände werden berechnet …",
]

if los and gewaehlter_ort:
    bar = st.progress(0.0, text=LADETEXTE[0])
    alle_daten = lade_alle_daten(gewaehlter_ort['lat'], gewaehlter_ort['lon'],
                                 af_aktiv, tage, fortschritt=bar,
                                 standorthoehe=gewaehlter_ort.get('hoehe'),
                                 bodenart=bodenart_wahl)
    bar.progress(0.95, text="Modelle werden zusammengeführt …")
    with st.spinner("Bedingungen werden für Ihr Vorhaben bewertet …"):
        konsens = berechne_konsens(alle_daten, af_aktiv, tage)
        konsens = wende_trockenfenster_an(konsens, af_aktiv)
    bar.empty()
    st.session_state['konsens'] = konsens
    st.session_state['alle_daten'] = alle_daten
    st.session_state['kontext'] = {
        'ort': gewaehlter_ort['label'], 'anwendung': fall_name,
        'tage': tage, 'af': af_aktiv, 'kategorie': kategorie,
        'lat': gewaehlter_ort['lat'], 'lon': gewaehlter_ort['lon'],
        'hoehe': gewaehlter_ort.get('hoehe'),
        'bodenart': bodenart_wahl,
        'zeitpunkt': datetime.now().strftime('%d.%m.%Y, %H:%M Uhr')}
elif los and not gewaehlter_ort:
    st.warning("Bitte zuerst einen Standort eingeben.")

# ============================================================
# ERGEBNISDARSTELLUNG
# ============================================================

if 'konsens' in st.session_state:
    konsens = st.session_state['konsens']
    alle_daten = st.session_state['alle_daten']
    kontext = st.session_state['kontext']
    af_kontext = kontext.get('af', {})
    bodenindex = alle_daten.get('bodenindex')
    sonne = alle_daten.get('sonne')
    hoehe = kontext.get('hoehe')
    delta_h = alle_daten.get('delta_h')

    st.divider()
    st.subheader(f"{kontext['ort']} · {kontext['anwendung']} · "
                 f"{kontext['tage']} Tage")
    _stand = kontext.get('zeitpunkt')
    if _stand:
        notiz(f"Stand der Auswertung: {_stand}")

    # --- Hinweis auf unvollständige Datenbasis ---
    _n_haupt_geladen = len(alle_daten.get('haupt', {}))
    _n_ens_geladen = len(alle_daten.get('ensemble', {}))
    _n_haupt_erwartet = len(HAUPTLAUFE)
    _n_ens_erwartet = len(ENSEMBLE_MODELLE)
    # Regionalmodelle decken nur einen Ausschnitt ab. Fehlen sie, ist das
    # kein Fehler, sondern liegt daran, dass der Standort außerhalb ihres
    # Gebiets liegt. Nur global verfügbare Modelle lösen eine Warnung aus.
    _regional = {n for n, c in HAUPTLAUFE.items() if 'gebiet' in c}
    _fehlend_global = [n for n in HAUPTLAUFE
                       if n not in alle_daten.get('haupt', {})
                       and n not in _regional]
    _fehlend_global += [n for n in ENSEMBLE_MODELLE
                        if n not in alle_daten.get('ensemble', {})]
    _regional_aktiv = [n for n in _regional if n in alle_daten.get('haupt', {})]

    if _fehlend_global:
        st.warning(
            f"Einzelne Modelle sind derzeit nicht erreichbar: "
            f"{', '.join(_fehlend_global[:4])}"
            + (" und weitere" if len(_fehlend_global) > 4 else "")
            + f". Die Auswertung stützt sich auf die übrigen "
              f"{_n_haupt_geladen + _n_ens_geladen} Modelle.")

    if _regional_aktiv:
        _q = sorted({HAUPTLAUFE[n].get('quelle', '') for n in _regional_aktiv})
        _feinste = min(
            (HAUPTLAUFE[n]['aufloesung'] for n in _regional_aktiv),
            key=lambda a: float(str(a).split()[0].replace(',', '.')))
        st.success(
            f"Für diesen Standort liegen hochauflösende Regionalmodelle vor "
            f"({', '.join(_q)}, feinste Maschenweite {_feinste}). "
            f"Sie verbessern besonders die Kurzfristprognose im Bergland.")

    if hoehe is not None and delta_h is not None and abs(delta_h) >= 100:
        richtung = "kälter" if delta_h > 0 else "milder"
        # Mittlere Feuchte für einen realistischen Gradienten
        _f_mittel = 70.0
        if 'feuchte_median' in konsens.columns:
            _fm = pd.to_numeric(konsens['feuchte_median'],
                                errors='coerce').dropna()
            if not _fm.empty:
                _f_mittel = float(_fm.mean())
        _grad = 0.85 - 0.35 * (_f_mittel / 100.0)
        _dt = abs(delta_h) / 100.0 * _grad

        _text = (f"Höhenkorrektur aktiv. Standort {hoehe:.0f} m, "
                 f"Modellgitter {alle_daten.get('modellhoehe') or 0:.0f} m "
                 f"({delta_h:+.0f} m). Temperatur und Taupunkt um "
                 f"{_dt:.1f} °C {richtung} gerechnet "
                 f"(Gradient {_grad:.2f} °C je 100 m bei "
                 f"{_f_mittel:.0f} % Luftfeuchte), Wind und Böen "
                 f"entsprechend verstärkt.")

        # Schneefallgrenze bei alpinen Standorten ergänzen
        if hoehe >= 1000 and 'temp_median' in konsens.columns:
            _t_jetzt = pd.to_numeric(konsens['temp_median'],
                                     errors='coerce').dropna()
            if not _t_jetzt.empty:
                _sfg = schneefallgrenze(float(_t_jetzt.iloc[0]), hoehe, _f_mittel)
                if _sfg is not None and 0 < _sfg < 6000:
                    _lage = ("oberhalb des Standorts" if _sfg > hoehe
                             else "unterhalb des Standorts")
                    _text += (f" Schneefallgrenze aktuell bei rund "
                              f"{_sfg:.0f} m, also {_lage}.")
        st.info(_text)

    ziel, best, n_bloecke = finde_bestes_fenster(konsens)
    if best is not None:
        _start = best['start']
        _ende = best['ende'] + timedelta(hours=1)
        _heute = datetime.now().date()
        _tagdiff = (_start.date() - _heute).days
        if _tagdiff == 0:
            _tagwort = 'heute'
        elif _tagdiff == 1:
            _tagwort = 'morgen'
        elif _tagdiff == 2:
            _tagwort = 'übermorgen'
        else:
            _tagwort = (f'am {WOCHENTAGE_LANG.get(_start.strftime("%A"), "")}, '
                        f'{_start.strftime("%d.%m.")}')

        _dauer = best['stunden']
        _dauertext = ('eine Stunde' if _dauer == 1
                      else f'{_dauer} Stunden durchgehend')

        _sicher = {
            'sehr hoch': 'Die Modelle sind sich sehr einig.',
            'hoch': 'Die Modelle sind sich weitgehend einig.',
            'mittel': 'Die Modelle weichen teilweise voneinander ab.',
            'gering': 'Die Modelle weichen deutlich voneinander ab — '
                      'bitte kurzfristig erneut prüfen.',
        }.get(best['sicherheit'], '')

        _weitere = ''
        if n_bloecke > 1:
            _weitere = (f' Im Zeitraum gibt es {n_bloecke} solcher Fenster; '
                        f'angezeigt ist das längste.')

        if ziel == 'sehr gut':
            _kopf = (f'Beste Gelegenheit: {_tagwort} ab '
                     f'{_start.strftime("%H:%M")} Uhr')
            _sub = (f'{_dauertext} sehr gute Bedingungen, bis '
                    f'{_ende.strftime("%H:%M")} Uhr. {_sicher}{_weitere}')
            _farbe = '#eaf6ee'
            _rand = STUFEN[4]['farbe']
        elif ziel == 'gut':
            _kopf = (f'Brauchbares Fenster: {_tagwort} ab '
                     f'{_start.strftime("%H:%M")} Uhr')
            _sub = (f'{_dauertext} gute Bedingungen mit kleinen Abstrichen, '
                    f'bis {_ende.strftime("%H:%M")} Uhr. {_sicher}{_weitere}')
            _farbe = '#f0f7ea'
            _rand = STUFEN[3]['farbe']
        else:
            _kopf = (f'Nur bedingt geeignet: {_tagwort} ab '
                     f'{_start.strftime("%H:%M")} Uhr')
            _sub = (f'Für {_dauertext} liegen die Bedingungen im '
                    f'grenzwertigen Bereich, bis {_ende.strftime("%H:%M")} Uhr. '
                    f'Ein durchgehend gutes Fenster gibt es im gewählten '
                    f'Zeitraum nicht. {_sicher}')
            _farbe = '#fdf7e6'
            _rand = STUFEN[2]['farbe']

        st.markdown(
            f'<div class="ew-empf" style="background:{_farbe};'
            f'border-left:4px solid {_rand}">'
            f'<div class="ew-empf-t">{_kopf}</div>'
            f'<div class="ew-empf-s">{_sub}</div></div>',
            unsafe_allow_html=True)
    else:
        st.markdown(
            f'<div class="ew-empf" style="background:#fbeceb;'
            f'border-left:4px solid {STUFEN[0]["farbe"]}">'
            f'<div class="ew-empf-t">Kein geeignetes Zeitfenster</div>'
            f'<div class="ew-empf-s">In den kommenden '
            f'{kontext["tage"]} Tagen erfüllt keine zusammenhängende Phase '
            f'die gesetzten Anforderungen. Sie können die Richtwerte oben '
            f'anpassen oder den Zeitraum verlängern.</div></div>',
            unsafe_allow_html=True)

    # --- Wetterüberblick ---
    _spalten = baue_wetteruebersicht(konsens, max_tage=min(kontext['tage'], 7),
                                     sonne=sonne)
    if _spalten:
        abschnitt("Wetterüberblick",
                  "Höchst- und Tiefstwerte, Wetterlage nach Tagesabschnitten "
                  "mit Windrichtung sowie Sonnenscheindauer und "
                  "Niederschlagswahrscheinlichkeit je Tag.")
        st.markdown(wetteruebersicht_html(_spalten), unsafe_allow_html=True)

    zeige_boden = bool(af_kontext.get('boden_relevant')) and bodenindex is not None
    if zeige_boden:
        m = bodenindex['metriken']
        _bart = bodenindex.get('bodenart', BODENART_STANDARD)
        abschnitt("Bodenzustand",
                  f"Wasserbilanz der vergangenen zehn Tage, gerechnet für "
                  f"{_bart.lower()}")
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Niederschlag 3 Tage", f"{m['regen_3t']:.0f} mm")
        c2.metric("Niederschlag 7 Tage", f"{m['regen_7t']:.0f} mm")
        c3.metric("Letzter Niederschlag",
                  "heute oder gestern" if m['tage_seit_regen'] <= 1
                  else f"vor {m['tage_seit_regen']} Tagen")
        c4.metric("Wasserbilanz", f"{m['balance_heute']:.0f} mm")
        _hinw = bodenindex.get('bodenart_hinweis', '')
        if m['zustand_level'] >= 1:
            notiz(f"Aktuell: {m['zustand_text']}. Der Bodenzustand fließt in "
                  f"die Bewertung ein; betroffene Zeitfenster sind "
                  f"herabgestuft. Angenommene Bodenart: {_bart} — {_hinw}.")
        else:
            notiz(f"Angenommene Bodenart: {_bart} — {_hinw}. "
                  f"Die Bodenart lässt sich oben im Eingabebereich ändern.")

    abschnitt("Eignungsmatrix",
              "Stündliche Bewertung im gewichteten Konsens aller Modelle. "
              "Ein Feld antippen, um die Detailwerte zu sehen.")
    stufen_legende()
    fig, lookup = baue_heatmap(konsens, sonne=sonne)
    event = st.plotly_chart(fig, use_container_width=True, key="hm",
                            on_select="rerun", config=PLOT_CONFIG_HEATMAP)

    gewaehlt = None
    try:
        pts = event.selection.points if event and event.selection else []
        if pts:
            p = pts[0]
            gewaehlt = lookup.get((p['y'], int(p['x'])))
    except Exception:
        gewaehlt = None

    if gewaehlt:
        t = gewaehlt['time']
        st.markdown(f'<div class="ew-headline">Detailwerte — {tag_kurz(t)} '
                    f'{t.strftime("%d.%m.")}, {t.hour:02d}:00 Uhr</div>',
                    unsafe_allow_html=True)
        d1, d2, d3, d4 = st.columns(4)
        d1.metric("Eignung", gewaehlt['ampel'])
        d1.caption(f"Vorhersagesicherheit {gewaehlt['sicherheit']}")
        if gewaehlt['temp_median'] is not None:
            d2.metric("Temperatur", f"{gewaehlt['temp_median']:.0f} °C",
                      f"± {gewaehlt['temp_spread']:.0f} °C Streubreite",
                      delta_color="off")
        _gef = gewaehlt.get('gefuehlt')
        if _gef is not None and not pd.isna(_gef):
            d2.metric("gefühlt", f"{_gef:.0f} °C")
        if gewaehlt.get('taupunkt') is not None and not pd.isna(gewaehlt['taupunkt']):
            d2.caption(f"Taupunkt {gewaehlt['taupunkt']:.0f} °C")
        if gewaehlt['wind_median'] is not None:
            boe = gewaehlt.get('boeen')
            d3.metric("Wind", f"{gewaehlt['wind_median']:.0f} km/h",
                      (f"Böen bis {boe:.0f} km/h"
                       if boe is not None and not pd.isna(boe) else None),
                      delta_color="off")
        d3.metric("Niederschlag", f"{gewaehlt['ns_median']:.1f} mm/h",
                  f"{gewaehlt['ns_wahrscheinlichkeit']:.0f} % Wahrscheinlichkeit",
                  delta_color="off")
        _cape = gewaehlt.get('cape')
        if _cape is not None and not pd.isna(_cape) and float(_cape) >= 300:
            _cv = float(_cape)
            _ctext = ('hoch' if _cv >= 2000 else
                      'erhöht' if _cv >= 1200 else
                      'leicht erhöht' if _cv >= 800 else 'gering')
            d4.metric("Gewitterneigung", _ctext)
            d4.caption(f"CAPE {_cv:.0f} J/kg")
        else:
            d4.metric("Modell-Läufe", int(gewaehlt['n_laeufe']))
            d4.caption(f"{gewaehlt['n_ens_mitglieder']} Ensemble-Mitglieder, "
                       f"{gewaehlt['n_haupt']} Hauptläufe")
        if gewaehlt['gruende']:
            notiz(f"Bewertungsgrundlage: {gewaehlt['gruende']}")
    else:
        notiz("Senkrechte Striche kennzeichnen Sonnenaufgang und "
              "Sonnenuntergang des jeweiligen Tages.")

    abschnitt("Temperatur und Taupunkt",
              "Ensemble-Median mit Streubereich zwischen 10. und 90. Perzentil")
    ft = zeichne_temperatur(konsens)
    if ft is not None:
        st.plotly_chart(ft, use_container_width=True, key="temp",
                        config=PLOT_CONFIG)
        notiz("Nähert sich die Temperatur dem Taupunkt, steigen Nebel-, Tau- "
              "und Reifwahrscheinlichkeit; die Abtrocknung kommt zum Erliegen.")

    abschnitt("Niederschlag",
              "Stundensumme im Median und Eintrittswahrscheinlichkeit "
              "über alle Ensemble-Mitglieder")
    fn = zeichne_niederschlag(konsens)
    if fn is not None:
        st.plotly_chart(fn, use_container_width=True, key="ns",
                        config=PLOT_CONFIG)

    fw = zeichne_wind(konsens)
    if fw is not None:
        abschnitt("Wind",
                  "Mittlere Geschwindigkeit, Böenspitzen und Anströmrichtung")
        st.plotly_chart(fw, use_container_width=True, key="wind",
                        config=PLOT_CONFIG)

    with st.expander("Wie viele Modelle stecken dahinter?"):
        fl = zeichne_laeufe(konsens)
        if fl is not None:
            st.plotly_chart(fl, use_container_width=True, key="laeufe",
                            config=PLOT_CONFIG)
        st.caption(
            "Je mehr Rechenläufe zusammenkommen, desto belastbarer ist die "
            "Aussage. In den ersten beiden Tagen liefern zusätzlich "
            "hochauflösende Kurzfristmodelle Daten; danach bleiben die "
            "globalen Modelle, und die Vorhersage wird gröber.")

    fc = zeichne_bewoelkung(konsens)
    if fc is not None:
        abschnitt("Bewölkung",
                  "Bedeckungsgrad nach Schichthöhe und in Summe")
        st.plotly_chart(fc, use_container_width=True, key="wolken",
                        config=PLOT_CONFIG)
        notiz("Tiefe Bewölkung bremst die Abtrocknung am Boden. Hohe "
              "Bewölkung wirkt vor allem auf die nächtliche Ausstrahlung "
              "und damit auf das Frostrisiko.")

    if zeige_boden:
        fig_boden = zeichne_bodenprofil(alle_daten.get('boden'),
                                        alle_daten.get('infiltration'))
        if fig_boden is not None:
            abschnitt("Bodenfeuchte und Wasseraufnahme",
                      "Modellierte Feuchte nach Tiefe sowie der Anteil des "
                      "Niederschlags, der tatsächlich infiltriert")
            st.plotly_chart(fig_boden, use_container_width=True,
                            key="bodenprofil", config=PLOT_CONFIG)
            infil = alle_daten.get('infiltration')
            if infil is not None:
                jetzt = datetime.now()
                verg = infil[infil['time'] <= jetzt]
                zuk = infil[infil['time'] > jetzt]
                if not verg.empty:
                    ges = verg['precip_h'].sum()
                    rein = verg['ns_effektiv'].sum()
                    ab = verg['ns_abfluss'].sum()
                    b1, b2, b3 = st.columns(3)
                    b1.metric("Niederschlag zehn Tage", f"{ges:.0f} mm")
                    b2.metric("davon infiltriert", f"{rein:.0f} mm",
                              f"{rein / ges * 100:.0f} %" if ges > 0 else None,
                              delta_color="off")
                    b3.metric("Oberflächenabfluss", f"{ab:.0f} mm",
                              f"{ab / ges * 100:.0f} %" if ges > 0 else None,
                              delta_color="off")
                if not zuk.empty and zuk['ns_abfluss'].sum() > 3:
                    notiz(f"Prognostiziert laufen rund "
                          f"{zuk['ns_abfluss'].sum():.0f} mm oberflächlich ab "
                          f"und erreichen den Wurzelraum nicht.")
            notiz("Dunkle Färbung kennzeichnet hohe Bodenfeuchte. Bei hoher "
                  "Niederschlagsintensität übersteigt die Menge die "
                  "Aufnahmefähigkeit des Bodens. Modellwerte — die örtliche "
                  "Bodenart kann abweichen.")

    lat = kontext.get('lat')
    lon = kontext.get('lon')

    # ========================================================
    # KARTENANSICHTEN
    # ========================================================
    WINDY_MODELLE = {
        "ECMWF (Europäisches Zentrum)": "ecmwf",
        "ICON (DWD)": "icon",
        "GFS (NOAA)": "gfs",
    }

    def windy_karte(overlay, modell_key, hoehe_px=520, radar_range=-1):
        """
        Windy-Einbettung mit eingebauter Zeitleiste.

        radarRange=-1 blendet die Radar-Rückschau ein: Damit zeigt Windy
        die vergangenen Stunden als Radarbild und danach die Modellprognose
        auf derselben Zeitachse. Der Kalender bleibt bedienbar, sodass sich
        auch mehrere Tage im Voraus abrufen lassen.
        """
        if lat is None or lon is None:
            st.caption("Kein Standort verfügbar.")
            return
        components.iframe(
            f"https://embed.windy.com/embed2.html"
            f"?lat={lat}&lon={lon}&detailLat={lat}&detailLon={lon}"
            f"&width=650&height={hoehe_px}&zoom=8&level=surface"
            f"&overlay={overlay}&product={modell_key}"
            f"&menu=&message=&marker=true&calendar=now"
            f"&pressure=&type=map&location=coordinates&detail=false"
            f"&metricWind=km%2Fh&metricTemp=%C2%B0C"
            f"&radarRange={radar_range}",
            height=hoehe_px + 20)

    def modellauswahl(schluessel, standard="ECMWF (Europäisches Zentrum)"):
        """Übersichtliche Modellauswahl über der Karte."""
        st.markdown('<div class="ew-modellwahl">Modellauswahl</div>',
                    unsafe_allow_html=True)
        labels = list(WINDY_MODELLE.keys())
        wahl = st.radio("Modellauswahl", labels,
                        index=labels.index(standard),
                        horizontal=True, key=schluessel,
                        label_visibility="collapsed")
        return WINDY_MODELLE[wahl], wahl

    abschnitt("Niederschlagskarte",
              "Echte Radarmessung und Nowcast in Fünf-Minuten-Schritten, "
              "danach die Modellprognose in Stundenschritten — auf einer "
              "durchgehenden Zeitleiste.")
    with st.spinner("Niederschlagsraster wird geladen …"):
        _std = min(max(kontext['tage'], 2), 3) * 24
        # AROME liefert im Alpenraum die feinste Struktur; wenn es
        # nicht antwortet, greift die automatische Modellwahl.
        _raster = hole_niederschlagsraster(stunden=_std,
                                           modell='arome_seamless')
        if _raster is None:
            _raster = hole_niederschlagsraster(stunden=_std,
                                               modell='best_match')
    _ortsname = str(kontext.get('ort', 'Standort')).split(',')[0]
    eigene_radarkarte(lat, lon, _ortsname, _raster)
    if _raster is None:
        notiz("Das Modellraster konnte nicht geladen werden; es wird nur die "
              "Radarmessung angezeigt.")
    else:
        _mname = {'arome_seamless': 'GeoSphere AROME (2,5 km)',
                  'best_match': 'automatische Modellwahl'}.get(
                      _raster.get('modell', ''), _raster.get('modell', ''))
        _mw = _raster.get('maschen', 0.2) * 111
        notiz(f"Prognoseteil aus {_mname}, abgetastet auf einem Gitter von "
              f"rund {_mw:.0f} Kilometern. Die Radarbilder davor liegen in "
              f"deutlich feinerer Auflösung vor.")

    with st.expander("Niederschlagsprognose als Flächenkarte (Windy)"):
        _mod_regen, _mod_regen_label = modellauswahl("modell_regen")
        windy_karte("rain", _mod_regen, hoehe_px=480, radar_range=-1)
        st.markdown(
            f'<div class="ew-note">Ergänzende Flächendarstellung, '
            f'Modell <b>{_mod_regen_label}</b>. Quelle: Windy.com</div>',
            unsafe_allow_html=True)

    with st.expander("Windprognose"):
        _mod_wind, _mod_wind_label = modellauswahl("modell_wind")
        windy_karte("wind", _mod_wind, hoehe_px=480)
        st.markdown(
            f'<div class="ew-note">Windgeschwindigkeit und Anströmrichtung, '
            f'Modell <b>{_mod_wind_label}</b>. Quelle: Windy.com</div>',
            unsafe_allow_html=True)

    with st.expander("Temperaturprognose"):
        _mod_temp, _mod_temp_label = modellauswahl("modell_temp")
        windy_karte("temp", _mod_temp, hoehe_px=480)
        st.markdown(
            f'<div class="ew-note">Flächenhafte Temperaturverteilung, '
            f'Modell <b>{_mod_temp_label}</b>. Quelle: Windy.com</div>',
            unsafe_allow_html=True)

    with st.expander("Datengrundlage und verwendete Modelle"):
        cols = st.columns(2)
        with cols[0]:
            st.markdown("**Deterministische Hauptläufe**")
            for name in alle_daten['haupt']:
                _c = HAUPTLAUFE[name]
                _z = f"{name} — Gitterweite {_c['aufloesung']}"
                if _c.get('quelle'):
                    _z += f", {_c['quelle']}"
                st.caption(_z)
        with cols[1]:
            st.markdown("**Ensemble-Systeme**")
            for name in alle_daten['ensemble']:
                cfg = ENSEMBLE_MODELLE[name]
                st.caption(f"{name} — {cfg['mitglieder']} Mitglieder, "
                           f"Gitterweite {cfg['aufloesung']}")
        st.markdown("**Bewertungsmaßstab**")
        st.caption("Für jeden Parameter wird die Überschreitung des Grenzwerts "
                   "auf einen Prozentwert normiert. Aus Anzahl und Ausmaß der "
                   "Überschreitungen ergibt sich die Eignungsstufe: "
                   "sehr gut ohne Überschreitung, gut bei einer geringen, "
                   "bedingt ab 15 Prozent oder zwei Überschreitungen, "
                   "ungünstig ab 35 Prozent, ungeeignet ab 50 Prozent "
                   "beziehungsweise zwei deutlichen Überschreitungen.")
        if hoehe is not None:
            st.caption(f"Standorthöhe {hoehe:.0f} m über Adria, "
                       f"Modellgitterhöhe "
                       f"{alle_daten.get('modellhoehe') or 0:.0f} m, "
                       f"Temperaturgradient {TEMP_GRADIENT_PRO_100M} °C je "
                       f"100 Höhenmeter.")

    # ---------- Auswertung mitnehmen ----------
    st.divider()
    abschnitt("Auswertung mitnehmen",
              "Die Stundenwerte als Tabelle für eigene Aufzeichnungen")
    _export = konsens[['time', 'ampel', 'sicherheit', 'temp_median',
                       'gefuehlt', 'wind_median', 'boeen', 'ns_median',
                       'ns_wahrscheinlichkeit', 'wolken', 'gruende']].copy()
    _export.columns = ['Zeitpunkt', 'Eignung', 'Vorhersagesicherheit',
                       'Temperatur °C', 'gefühlt °C', 'Wind km/h',
                       'Böen km/h', 'Niederschlag mm/h',
                       'Regenwahrscheinlichkeit %', 'Bewölkung %',
                       'Bewertungsgrundlage']
    for _sp in _export.columns[3:10]:
        _export[_sp] = pd.to_numeric(_export[_sp], errors='coerce').round(1)
    _csv = _export.to_csv(index=False, sep=';', decimal=',',
                          encoding='utf-8-sig')
    _name = (f"EnsembleWetter_{kontext['ort'].split(',')[0]}_"
             f"{kontext['anwendung'].split('/')[0].strip()}_"
             f"{datetime.now().strftime('%Y-%m-%d')}.csv")
    st.download_button(
        "Stundenwerte als Tabelle herunterladen",
        data=_csv, file_name=_name.replace(' ', '_'),
        mime='text/csv', use_container_width=True)
    notiz("Die Datei lässt sich in Excel oder LibreOffice öffnen "
          "(Semikolon als Trennzeichen).")

    # ---------- Fußbereich ----------
    st.markdown(
        f'<div class="ew-fuss">'
        f'<b>EnsembleWetter {APP_VERSION}</b> — Präzisionsprognose für '
        f'Landwirtschaft, Bau und Alpinraum.<br>'
        f'Datenquellen über Open-Meteo: ECMWF, DWD ICON, NOAA GFS, '
        f'Météo-France ARPEGE sowie die hochauflösenden Alpenmodelle '
        f'GeoSphere AROME (Österreich) und MeteoSchweiz ICON-CH. '
        f'Radarbilder: RainViewer. Karten: OpenStreetMap, Esri.<br><br>'
        f'<b>Hinweis zur Nutzung:</b> Die Auswertung beruht auf '
        f'Modellrechnungen und ersetzt keine amtliche Wetterwarnung. '
        f'Im Alpinraum ersetzt sie weder den Lawinenlagebericht noch eine '
        f'sorgfältige Tourenplanung. Bei Arbeiten mit '
        f'Pflanzenschutzmitteln gelten die Vorgaben der Zulassung und die '
        f'behördlichen Anwendungsbestimmungen unabhängig von dieser '
        f'Auswertung. Die Verantwortung für Entscheidungen bleibt beim '
        f'Anwender.'
        f'</div>', unsafe_allow_html=True)

else:
    st.info("Standort und Tätigkeit oben auswählen, anschließend auf "
            "„Analyse starten“ tippen.")
